package com.shengxu.controller;
import com.shengxu.dto.*; import com.shengxu.dto.MusicDtos.*; import com.shengxu.service.MusicLibraryService; import jakarta.servlet.http.HttpServletResponse; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/music-library") public class MusicLibraryController {private final MusicLibraryService s;public MusicLibraryController(MusicLibraryService s){this.s=s;}@GetMapping public ApiResponse<PageView<TrackView>> list(Authentication a,@RequestParam(required=false) String q,@RequestParam(defaultValue="all") String filter,@RequestParam(defaultValue="1") long page,@RequestParam(defaultValue="12") long pageSize){return ApiResponse.ok(s.list((Long)a.getPrincipal(),q,filter,page,pageSize));}@GetMapping("/share/{token}") public ApiResponse<SharedTrackView> shared(@PathVariable String token){return ApiResponse.ok(s.shared(token));}@GetMapping("/{id}") public ApiResponse<TrackView> get(Authentication a,@PathVariable Long id){return ApiResponse.ok(s.get((Long)a.getPrincipal(),id));}@PatchMapping("/{id}/favorite") public ApiResponse<TrackView> favorite(Authentication a,@PathVariable Long id,@jakarta.validation.Valid @RequestBody MusicDtos.FavoriteRequest in){return ApiResponse.ok(s.favorite((Long)a.getPrincipal(),id,in.favorite()));}@DeleteMapping("/{id}") public ApiResponse<Void> delete(Authentication a,@PathVariable Long id){s.delete((Long)a.getPrincipal(),id);return ApiResponse.ok(null);}@GetMapping("/{id}/download") public void download(Authentication a,@PathVariable Long id,HttpServletResponse response){s.download((Long)a.getPrincipal(),id,response);}@GetMapping("/{id}/comments") public ApiResponse<PageView<CommentView>> comments(Authentication a,@PathVariable Long id,@RequestParam(defaultValue="1") long page,@RequestParam(defaultValue="20") long pageSize){return ApiResponse.ok(s.commentList((Long)a.getPrincipal(),id,page,pageSize));}@PostMapping("/{id}/comments") public ApiResponse<CommentView> addComment(Authentication a,@PathVariable Long id,@jakarta.validation.Valid @RequestBody CommentRequest in){return ApiResponse.ok(s.addComment((Long)a.getPrincipal(),id,in));}@DeleteMapping("/{id}/comments/{commentId}") public ApiResponse<Void> deleteComment(Authentication a,@PathVariable Long id,@PathVariable Long commentId){s.deleteComment((Long)a.getPrincipal(),id,commentId);return ApiResponse.ok(null);}@PostMapping("/{id}/share") public ApiResponse<ShareView> share(Authentication a,@PathVariable Long id){return ApiResponse.ok(s.createShare((Long)a.getPrincipal(),id));}}
